After:
func requireServedReceiverAgentCollision(t *testing.T, selectedProofEndpoint string, selectedProofReadRunDeliveries servedRunDeliveryReader, selectedProofReceiverStateReader receiverProofStateReader, selectedProofRuntime *runtimepkg.Runtime, runID string, want map[string]any, turns int) map[string]any {
	t.Helper()
	deadline := time.Now().Add(30 * time.Second)
	for {
		completed, err := readServedSelectedRole(context.Background(), selectedProofReceiverStateReader, func(ctx context.Context) (int, error) {
			return storetest.CountReceiverLiveParsedTurnsStorage(ctx, selectedProofReceiverStateReader, runID)
		})
		if err != nil {
			t.Fatal(err)
		}
		var failed int
		if err := func() error {
			var err error
			failed, err = readServedRunDeadLetterCount(context.Background(), selectedProofReceiverStateReader, runID)
			return err
		}(); err != nil {
			t.Fatal(err)
		}
		if failed != 0 {
			t.Fatalf("configured agent journey dead-lettered\n%s", servedInspectionRunDebugSummary(selectedProofReceiverStateReader, runID))
		}
		if completed >= turns {
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("agent turns=%d want=%d\n%s", completed, turns, servedInspectionRunDebugSummary(selectedProofReceiverStateReader, runID))
		}
		time.Sleep(20 * time.Millisecond)
	}
	waitServedRunDeliveryQuiescence(t, selectedProofReadRunDeliveries, runID)
	record, receiver := requireSingleReceiverTargetState(t, selectedProofReceiverStateReader, runID, "account")
	path, entityID, flowRaw := receiver.StorageRef, receiver.EntityID, record.Lifecycle.Config
	agent, err := readServedSelectedRole(context.Background(), selectedProofReceiverStateReader, func(ctx context.Context) (storetest.ReceiverAgentIdentityStorage, error) {
		return storetest.ReadReceiverAgentIdentityStorage(ctx, selectedProofReceiverStateReader, runID, path)
	})
	if err != nil {
		t.Fatal(err)
	}
	agentID, raw, descriptor, tools, permissions, model := agent.ID, agent.Config, agent.Descriptor, agent.Tools, agent.Permissions, agent.Model
	memory := agent.Memory
	var envelope, flow map[string]any
	if err := canonicaljson.DecodePreservingNumberLexemes([]byte(raw), &envelope); err != nil {
		t.Fatal(err)
	}
	if err := canonicaljson.DecodePreservingNumberLexemes(flowRaw, &flow); err != nil {
		t.Fatal(err)
	}
	check := func(got any) {
		a, err := canonicaljson.MarshalPreservingNumberKinds(got)
		if err != nil {
			t.Fatal(err)
		}
		b, err := canonicaljson.MarshalPreservingNumberKinds(want)
		if err != nil {
			t.Fatal(err)
		}
		if string(a) != string(b) {
			t.Fatalf("business config=%s want=%s", a, b)
		}
	}
	fields := receiver.Fields
	check(map[string]any{"account_id": fields["account_id"], "values": fields["values"]})
	if _, exists := flow["config"]; exists {
		t.Fatalf("business copy in runtime header: %s", flowRaw)
	}
	if len(envelope) != 0 {
		t.Fatalf("not ordinary opaque agent config: %s", raw)
	}
	matched := 0
	for _, cfg := range selectedProofRuntime.Manager.ListAgentConfigs() {
		if cfg.Identity.RunID != runID || cfg.ID != agentID || cfg.FlowPath != path {
			continue
		}
		matched++
		if string(cfg.Config) != "{}" || cfg.Model != "regular" || cfg.Memory.Enabled || len(cfg.Tools) != 0 || len(cfg.Permissions) != 0 || cfg.NativeTools.Any() {
			t.Fatalf("live actor authority changed: %+v", cfg)
		}
		prompt, err := cfg.DerivedSystemPrompt()
		if err != nil || !strings.Contains(prompt, "AUTHORED_COLLISION_OBSERVER") || strings.Contains(prompt, "INERT_") {
			t.Fatalf("live actor prompt changed: %q: %v", prompt, err)
		}
	}
	if matched != 1 {
		t.Fatalf("exact configured live actor count=%d want=1", matched)
	}
	var authority map[string]any
	if err := json.Unmarshal([]byte(descriptor), &authority); err != nil {
		t.Fatal(err)
	}
	if model != "regular" || memory || authority["execution_mode"] != "live" || !strings.Contains(descriptor, "AUTHORED_COLLISION_OBSERVER") {
		t.Fatalf("business values replaced authority: model=%s memory=%v descriptor=%s", model, memory, descriptor)
	}
	for _, rawList := range []string{tools, permissions} {
		var names []string
		if err := json.Unmarshal([]byte(rawList), &names); err != nil {
			t.Fatal(err)
		}
		if len(names) != 0 {
			t.Fatalf("business data granted actor tools/permissions: %s", rawList)
		}
	}
	for _, key := range []string{"INERT_ARCHIVED_PROMPT", "INERT_LIST_PROMPT", "business-model", "business-memory"} {
		if strings.Contains(descriptor, key) {
			t.Fatalf("business data in descriptor: %s", descriptor)
		}
	}
	var detail operatorread.OperatorAgentDetail
	requireServedJSONRPCResult(t, selectedProofEndpoint, "agent.get", map[string]any{"run_id": runID, "agent_id": agentID, "flow_instance": path}, &detail)
	if detail.Agent.AgentID != agentID || detail.Agent.FlowInstance != path || detail.Agent.ExecutionMode != "live" {
		t.Fatalf("public agent identity: %+v", detail)
	}
	var entity operatorread.OperatorEntityFull
	requireServedJSONRPCResult(t, selectedProofEndpoint, "entity.get", map[string]any{"run_id": runID, "entity_id": entityID}, &entity)
	if entity.Entity.EntityID != entityID || entity.Entity.FlowInstance != path || entity.Fields["processed_count"] != float64(turns) {
		t.Fatalf("public receiver state: %+v", entity)
	}
	count, err := readServedSelectedRole(context.Background(), selectedProofReceiverStateReader, func(ctx context.Context) (int, error) {
		return storetest.CountReceiverRunTurnsStorage(ctx, selectedProofReceiverStateReader, runID)
	})
	if err != nil {
		t.Fatal(err)
	}
	deliveries, err := readServedSelectedRole(context.Background(), selectedProofReceiverStateReader, func(ctx context.Context) (int, error) {
		return storetest.CountReceiverFirstClaimAgentDeliveriesStorage(ctx, selectedProofReceiverStateReader, runID)
	})
	if err != nil {
		t.Fatal(err)
	}
	if count != turns || deliveries != turns {
		t.Fatalf("turns/delivered first claims=%d/%d want=%d", count, deliveries, turns)
	}
	return map[string]any{"agent": agentID, "path": path, "entity": entityID, "descriptor": authority, "tools": tools, "permissions": permissions, "memory": memory, "model": model, "config": envelope}
}

