		deliveryReader = p.deps.DeliveryStore.SummarizeRun
	})
	unsetStoreSelectorEnv(t)
	stubServeRuntimeWorkspaceLifecycle(t)
	var db *sql.DB
	opts := cliapp.ServeOptions{SourceRoot: root, PlatformSpecPath: defaultPlatformSpecPath, APIListenAddr: "127.0.0.1:0", MCPListenAddr: "127.0.0.1:0", SelfCheck: true, TestOutboxSweeperConfig: servedEventPublishProofOutboxSweeperConfig()}
	dialect := "sqlite"
	if backend == servedparity.BackendExplicitPostgres {
		dialect = "postgres"
		_, db, _ = installServeRuntimeEmptyPostgresTestStores(t, func() cliapp.ServeWorkspaceLifecycle {
			return serveRuntimeWorkspaceStub{}
		})
		opts.StoreMode, opts.StoreModeSet = dialect, true
		opts.ConfigPath = writeMockAgentRuntimeConfig(t, dialect, "")
	} else {
		opts.ConfigPath = writeMockAgentRuntimeConfig(t, dialect, filepath.Join(t.TempDir(), "numeric.db"))
	}
	captureSelectedRuntimePersistence(t, func(p serveRuntimePersistence) {
		db, _, _ = selectedRuntimeStoreForTest(t, p)
	})
	retainedRoot := t.TempDir()
	start := func() (*serveRuntimeTestProcess, servedControlProofRuntime) {
		var process *serveRuntimeTestProcess
		if mock {
			t.Log("proof_surface=H retained MockOnly composition; not public serve or private-test lifetime")
			process = startOwnedMockLifecycleTestProcess(t, repoRootForTest(), retainedRoot, opts)
		} else {
			process = startServeRuntimeTestProcess(t, opts)
		}
		process.waitForReadyLine()
		endpoint := "http://" + serveRuntimeAPIListenerFromOutput(t, process.outputString()) + "/v1/rpc"
		return process, servedControlProofRuntime{ReadRunDeliveries: deliveryReader, Endpoint: endpoint, DB: db, Backend: dialect, BundleHash: servedEventPublishFixtureBundleHash(t, root), Runtime: servedTestProcessRuntime(t, process)}
	}
	process, rt := start()
	return rt, func() servedControlProofRuntime {
		t.Helper()
		if code := process.stop(); code != 0 {
			t.Fatalf("numeric runtime stop=%d", code)
		}
		var restarted servedControlProofRuntime
		process, restarted = start()
		return restarted
	}
}

